package com.realstant.nativegame; import java.util.*; public final class Leaderboard { private final List<LeaderboardEntry> rows=new ArrayList<>(); public void add(String n,float t){rows.add(new LeaderboardEntry(n,t));rows.sort((a,b)->Float.compare(a.time,b.time));if(rows.size()>10)rows.remove(rows.size()-1);} public List<LeaderboardEntry> rows(){return Collections.unmodifiableList(rows);} }
